  ('33dfb143-911c-5383-a252-663394a49a8c', 'דנה לוי', 'img/face0.jpg', 'סטודנטית לתואר שני במתמטיקה', 'מלמדת מתמטיקה כבר שש שנים, בעיקר 5 יח״ל ושנה א׳ באוניברסיטה. אני מתחילה כל שיעור מהשאלה שתקועה לכם, ובונה משם את ההבנה עד שזה יושב. בין התלמידים שלי יש כאלה שעלו מ־60 ל־95 בבגרות.', array['מתמטיקה', 'סטטיסטיקה']::text[], array['4 יח״ל', '5 יח״ל', 'אקדמיה']::text[], array['חדו״א', 'הסתברות', 'שאלון 581', 'שאלון 582', 'חדו״א 1', 'מבוא לסטטיסטיקה', 'סטטיסטיקה תיאורית']::text[], array['0-16', '0-18', '1-16', '1-18', '3-16', '3-18']::text[], 'רמת גן', 'ליד הבורסה', 32.0684, 34.8248, true, true, 140, 150, 6, true, 212, '2026-10-01T10:00:00Z', true),
  ('3c088bce-f969-56ae-acec-5ad93fd69216', 'מיכאל רוזן', 'img/face2.jpg', 'מורה למתמטיקה בתיכון, 22 שנות ניסיון', 'רכז מתמטיקה בתיכון בחיפה. מכיר את מבנה הבגרות לפרטי פרטים ויודע אילו שאלות חוזרות כל שנה. מתאים במיוחד לתלמידים שצריכים סדר ושיטה.', array['מתמטיקה', 'פיזיקה']::text[], array['3 יח״ל', '4 יח״ל', '5 יח״ל']::text[], array['גאומטריה', 'טריגונומטריה', 'חדו״א', 'שאלון 471', 'שאלון 472', 'מכניקה']::text[], array['1-10', '1-12', '1-16', '2-10', '2-12', '2-16', '4-10', '4-12', '4-16', '5-10']::text[], 'חיפה', 'כרמל', 32.794, 34.9896, true, true, 160, 170, 22, true, 340, '2026-10-01T10:00:00Z', true),
  ('4d93f015-a744-52d9-a7b3-de3ee4faa045', 'נועה פרידמן', 'img/face3.jpg', 'סטודנטית להנדסת חשמל בטכניון', 'שיעורים אונליין עם לוח משותף והקלטה של כל שיעור. קיבלתי 780 בפסיכומטרי ואני מלמדת את החלק הכמותי עם הרבה טריקים לחיסכון בזמן.', array['מתמטיקה', 'פיזיקה', 'פסיכומטרי']::text[], array['חטיבת ביניים', '3 יח״ל', 'פסיכומטרי']::text[], array['אלגברה', 'שאלון 371', 'חשמל ומגנטיות', 'חשיבה כמותית', 'מבחן מימד']::text[], array['0-14', '0-16', '0-18', '2-14', '2-16', '2-18', '3-14', '3-16', '3-18']::text[], 'חיפה', null, 32.794, 34.9896, true, false, 110, null, 3, true, 96, '2026-10-01T10:00:00Z', true),
  ('050961cb-a3b4-5776-a3f6-3e0919f22837', 'עומר בן דוד', 'img/face1.jpg', 'מפתח תוכנה ומרצה במכללה', 'מלמד מבוא למדעי המחשב, מבני נתונים ופייתון, וגם בדידה וחדו״א לסטודנטים. אני מביא דוגמאות מהעבודה כדי שהחומר יהיה מוחשי.', array['מדעי המחשב', 'מתמטיקה']::text[], array['5 יח״ל', 'אקדמיה']::text[], array['Python', 'מבני נתונים', 'מבוא למדעי המחשב', 'אלגוריתמים', 'אלגברה לינארית 1', 'מתמטיקה בדידה']::text[], array['0-16', '0-18', '0-20', '3-16', '3-18', '3-20', '4-16', '4-18', '4-20', '5-10']::text[], 'תל אביב', 'פלורנטין', 32.0853, 34.7818, true, true, 160, 180, 8, true, 120, '2026-10-01T10:00:00Z', true),
  ('0cc19d22-7e4d-5e1f-a828-5e7aca3ae7d7', 'רחל אברהם', 'img/face4.jpg', 'מורה לאנגלית, לשעבר בודקת בגרויות', 'הייתי בודקת בגרויות באנגלית שמונה שנים, אז אני יודעת בדיוק על מה מורידים נקודות. מלמדת בבית שלי בכפר סבא או בזום.', array['אנגלית', 'לשון']::text[], array['יסודי', 'חטיבת ביניים', '4 יח״ל', '5 יח״ל']::text[], array['הבנת הנקרא (Unseen)', 'כתיבה', 'אוצר מילים ודקדוק', 'תחביר']::text[], array['1-18', '1-20', '3-18', '3-20']::text[], 'כפר סבא', null, 32.175, 34.907, true, true, 130, 140, 18, true, 150, '2026-10-01T10:00:00Z', true),
  ('dd4a85e4-89e9-5c7b-a0e7-f69ef257d984', 'יוסי מזרחי', 'img/face5.jpg', 'מהנדס כימיה, מורה פרטי בערבים', 'כימיה ומתמטיקה בגובה העיניים. סבלני מאוד, מתאים גם לתלמידים עם לקויות למידה.', array['כימיה', 'מתמטיקה', 'פיזיקה']::text[], array['3 יח״ל', '4 יח״ל', '5 יח״ל']::text[], array['כימיה אורגנית', 'חומצות ובסיסים', 'אלגברה', 'מכניקה']::text[], array['0-16', '0-18', '1-16', '1-18', '3-16', '3-18', '5-10']::text[], 'באר שבע', null, 31.252, 34.7915, true, true, 110, 120, 10, true, 70, '2026-10-01T10:00:00Z', true),
  ('c95120f8-5e8a-5e63-aa0d-6eedeb11c365', 'גיל שמש', null, 'סטודנט שנה ב׳ למתמטיקה', 'התחלתי ללמד השנה. מחיר נמוך לתלמידי חטיבה ותיכון.', array['מתמטיקה']::text[], array['חטיבת ביניים', '3 יח״ל', '4 יח״ל']::text[], array['אלגברה', 'גאומטריה', 'שאלון 371']::text[], array['1-10', '1-12', '1-16', '2-10', '2-12', '2-16', '4-10', '4-12', '4-16']::text[], 'ירושלים', 'גבעת רם', 31.7683, 35.2137, true, true, 80, 90, 1, false, 8, '2026-10-01T10:00:00Z', true),
  ('446bd82a-ade4-5829-adb9-40fa9d6298af', 'שירה כהן', null, 'מורה למתמטיקה ביסודי ובחטיבה', 'מלמדת ילדים בכיתות ג׳ עד ט׳. משחקים, דפי עבודה ובעיקר הרבה ביטחון עצמי.', array['מתמטיקה', 'אנגלית']::text[], array['יסודי', 'חטיבת ביניים']::text[], array['חשבון', 'שברים ואחוזים', 'אוצר מילים ודקדוק']::text[], array['0-14', '0-16', '0-18', '2-14', '2-16', '2-18', '3-14', '3-16', '3-18', '5-10']::text[], 'ראשון לציון', null, 31.973, 34.7925, true, true, 90, 100, 7, true, 88, '2026-10-01T10:00:00Z', true),
  ('221c7844-67a4-5752-a90e-ce9905b95a25', 'אלון ברק', null, 'דוקטורנט לפיזיקה', 'פיזיקה 5 יח״ל, מכניקה וחשמל לסטודנטים. אני מסביר את האינטואיציה לפני הנוסחה.', array['פיזיקה', 'מתמטיקה']::text[], array['5 יח״ל', 'אקדמיה']::text[], array['מכניקה', 'חשמל ומגנטיות', 'פיזיקה 1', 'פיזיקה 2', 'חדו״א 2', 'משוואות דיפרנציאליות']::text[], array['0-16', '0-18', '0-20', '3-16', '3-18', '3-20', '4-16', '4-18', '4-20']::text[], 'רחובות', 'ליד מכון ויצמן', 31.8928, 34.8113, true, true, 180, 200, 9, true, 64, '2026-10-01T10:00:00Z', true),
  ('61fd215d-178a-5663-a4fc-5f634630b194', 'מאיה גולן', null, 'מורה לפסיכומטרי כבר 10 שנים', 'הכנה אישית לפסיכומטרי בשלושת הפרקים. הממוצע של התלמידים שלי בשנה האחרונה עלה ב־92 נקודות.', array['פסיכומטרי', 'אנגלית', 'מתמטיקה']::text[], array['פסיכומטרי']::text[], array['חשיבה כמותית', 'חשיבה מילולית', 'אנגלית', 'כתיבת חיבור']::text[], array['1-18', '1-20', '3-18', '3-20', '5-10']::text[], 'תל אביב', 'הצפון הישן', 32.0853, 34.7818, true, true, 170, 190, 10, true, 180, '2026-10-01T10:00:00Z', true),
  ('be82dafb-c3b7-5ba9-ac8d-868687f0d80f', 'חן אוחיון', null, 'סטודנטית לביולוגיה', 'ביולוגיה לבגרות כולל עבודת מעבדה ותצפית.', array['ביולוגיה', 'כימיה']::text[], array['חטיבת ביניים', '5 יח״ל']::text[], array['התא', 'גנטיקה', 'מבנה וקישור']::text[], array['0-16', '0-18', '1-16', '1-18', '3-16', '3-18']::text[], 'נתניה', null, 32.3215, 34.8532, true, true, 100, 110, 2, true, 22, '2026-10-01T10:00:00Z', true),
  ('08c8fea2-f468-565a-ad96-554ea3f52978', 'אריאל נחום', null, 'מורה למתמטיקה ומדעי המחשב', 'מלמד בתיכון במודיעין. שיעורים בבית התלמיד באזור מודיעין ושוהם.', array['מתמטיקה', 'מדעי המחשב']::text[], array['4 יח״ל', '5 יח״ל']::text[], array['וקטורים', 'מספרים מרוכבים', 'שאלון 581', 'Java', 'יסודות התכנות']::text[], array['1-10', '1-12', '1-16', '2-10', '2-12', '2-16', '4-10', '4-12', '4-16', '5-10']::text[], 'מודיעין', null, 31.898, 35.0104, true, true, 120, 130, 5, true, 41, '2026-10-01T10:00:00Z', true),
  ('83a0364e-6fa6-5379-a406-a0e52e439a52', 'ליאת שגיא', null, 'מורה ללשון ולספרות', 'לשון ספרות והיסטוריה לבגרות, עם סיכומים מסודרים לכל נושא.', array['לשון', 'ספרות', 'היסטוריה']::text[], array['חטיבת ביניים', '3 יח״ל', '4 יח״ל', '5 יח״ל']::text[], array['תחביר', 'שירה', 'סיפור קצר', 'לאומיות וציונות']::text[], array['0-14', '0-16', '0-18', '2-14', '2-16', '2-18', '3-14', '3-16', '3-18']::text[], 'פתח תקווה', null, 32.084, 34.8878, true, true, 110, 120, 12, true, 35, '2026-10-01T10:00:00Z', true),
  ('0de12077-db77-5f1b-ac06-c7d7900bf768', 'רון אלמוג', null, 'סטודנט להנדסה, בוגר 5 יח״ל ב־100', 'מתמטיקה ופיזיקה 5 יח״ל. שיעור ראשון של חצי שעה בלי תשלום כדי לראות שיש התאמה.', array['מתמטיקה', 'פיזיקה']::text[], array['4 יח״ל', '5 יח״ל']::text[], array['חדו״א', 'וקטורים', 'שאלון 581', 'מכניקה']::text[], array['0-16', '0-18', '0-20', '3-16', '3-18', '3-20', '4-16', '4-18', '4-20', '5-10']::text[], 'הרצליה', null, 32.1663, 34.8433, true, true, 100, 120, 2, true, 30, '2026-10-01T10:00:00Z', true),
  ('caa9d4bf-4e04-58e1-a17f-71e4378ea766', 'אביטל כהן', null, 'דוקטורנטית למתמטיקה בטכניון', 'מלמדת קורסי מתמטיקה של שנה א׳ ו־ב׳ בטכניון ובאוניברסיטת חיפה. פותרת איתכם מבחנים קודמים של הקורס שלכם, עם דגש על הוכחות.', array['מתמטיקה']::text[], array['אקדמיה']::text[], array['חדו״א 1', 'חדו״א 2', 'אינפי 1', 'אלגברה לינארית 1', 'אלגברה לינארית 2', 'אלגברה מופשטת', 'פונקציות מרוכבות']::text[], array['1-18', '1-20', '3-18', '3-20']::text[], 'חיפה', 'נווה שאנן', 32.794, 34.9896, true, true, 170, 190, 7, true, 140, '2026-10-01T10:00:00Z', true),
  ('ed06c609-77f4-57d1-a909-b0ac30b1b49a', 'יוסי בן דוד', null, 'מורה ותיק למתמטיקה, מתמחה ב־3 ו־4 יח״ל', 'עשרים וחמש שנים בכיתה. מתמחה בתלמידים שחוששים ממתמטיקה ובונה איתם ביטחון צעד אחר צעד עד הבגרות.', array['מתמטיקה']::text[], array['חטיבת ביניים', '3 יח״ל', '4 יח״ל']::text[], array['אלגברה', 'גאומטריה', 'הסתברות', 'שאלון 371', 'שאלון 372', 'שאלון 471']::text[], array['0-16', '0-18', '1-16', '1-18', '3-16', '3-18', '5-10']::text[], 'באר שבע', 'רמות', 31.252, 34.7915, true, true, 100, 110, 25, true, 260, '2026-10-01T10:00:00Z', true),
  ('3bf8b778-fe93-5464-ab11-fb020065a990', 'שירה מלכה', null, 'מתכנתת ומורה למדעי המחשב', 'מפתחת תוכנה בהייטק ומלמדת בערבים. Java ו־Python לבגרות, ומבוא ומבני נתונים לסטודנטים. כל שיעור כולל קוד אמיתי שכותבים יחד.', array['מדעי המחשב']::text[], array['5 יח״ל', 'אקדמיה']::text[], array['Java', 'Python', 'מבוא למדעי המחשב', 'מבני נתונים', 'תכנות מונחה עצמים']::text[], array['1-10', '1-12', '1-16', '2-10', '2-12', '2-16', '4-10', '4-12', '4-16']::text[], 'תל אביב', 'פלורנטין', 32.0853, 34.7818, true, false, 170, null, 5, true, 95, '2026-10-01T10:00:00Z', true),
  ('a02d072d-10bf-59bf-a4e9-60d54be009b3', 'אחמד חורי', null, 'מורה לערבית ולאנגלית', 'מלמד ערבית לבגרות ושיחה בערבית מדוברת למבוגרים, וגם אנגלית לחטיבה ולתיכון. סבלני, מסודר ועם הרבה חומרי תרגול.', array['ערבית', 'אנגלית']::text[], array['חטיבת ביניים', '3 יח״ל', '4 יח״ל', '5 יח״ל']::text[], array['דקדוק', 'שיחה (ערבית מדוברת)', 'הבנת הנקרא', 'אוצר מילים ודקדוק', 'הבנת הנקרא (Unseen)']::text[], array['0-14', '0-16', '0-18', '2-14', '2-16', '2-18', '3-14', '3-16', '3-18', '5-10']::text[], 'נצרת', null, 32.6996, 35.3035, true, true, 90, 100, 11, true, 77, '2026-10-01T10:00:00Z', true),
