  ('52ad8e55-7926-5a5c-acc1-c7ff04decd97', 'רועי פישר', null, 'מורה למתמטיקה, אילת והערבה', 'מתמטיקה לבגרות ומדעי המחשב בשפת Java. שיעורים בבית התלמיד באילת או אונליין.', array['מתמטיקה', 'מדעי המחשב']::text[], array['3 יח״ל', '4 יח״ל', '5 יח״ל']::text[], array['אלגברה', 'חדו״א', 'שאלון 371', 'שאלון 471', 'Java', 'יסודות התכנות']::text[], array['1-10', '1-12', '1-16', '2-10', '2-12', '2-16', '4-10', '4-12', '4-16', '5-10']::text[], 'אילת', null, 29.5577, 34.9519, true, true, 110, 120, 6, true, 30, '2026-10-01T10:00:00Z', true);
