insert into public.groups (id, tutor_id, title, subject, level, description, start_date, time, sessions, mode, city, location, price_per_person, max_seats, join_mode, created_at) values
  ('b5e5ba91-01ba-5394-a5d0-0b2b963ce502', '3c088bce-f969-56ae-acec-5ad93fd69216', 'מרתון לבגרות 472', 'מתמטיקה', '4 יח״ל', 'יום מרתון אחד לפני הבגרות: חוזרים על כל סוגי השאלות בשאלון 472, פותרים בחינה מלאה מהשנה שעברה ומסיימים עם דף טיפים. מקבלים הקלטה של המרתון.', '2026-11-17', '09:00–15:00', 1, 'online', null, null, 90, 12, 'open', '2026-10-20T10:00:00Z'),
  ('51b0de19-0a42-50ec-a7f6-a861da542b38', '33dfb143-911c-5383-a252-663394a49a8c', 'הכנה לבגרות 582, שמונה מפגשים', 'מתמטיקה', '5 יח״ל', 'קבוצה קטנה של עד שישה תלמידים. כל מפגש נושא אחד: חדו״א, וקטורים, מרוכבים וגדילה ודעיכה, עם שיעורי בית ובדיקה.', '2026-11-14', 'ימי ג׳ 18:00', 8, 'online', null, null, 70, 6, 'approval', '2026-10-20T10:00:00Z'),
  ('c3d14d23-b00f-5bf5-aafa-cf72cad6a37e', '4d93f015-a744-52d9-a7b3-de3ee4faa045', 'פסיכומטרי כמותי, קבוצת ערב', 'פסיכומטרי', 'פסיכומטרי', 'כל הנושאים בחשיבה כמותית, עם סימולציה מלאה כל שבועיים.', '2026-12-04', 'ימי ב׳ וד׳ 20:00', 12, 'online', null, null, 60, 6, 'open', '2026-10-20T10:00:00Z'),
  ('5ea402d2-70d1-5a43-a62c-f45213a26f00', '33dfb143-911c-5383-a252-663394a49a8c', 'גאומטריה ווקטורים, כיתה י״א', 'מתמטיקה', '4 יח״ל', 'מפגשים פרונטליים בכיתה קטנה ברמת גן. מתאים לתלמידי י״א שרוצים לסגור פערים בגאומטריה לפני המגן.', '2026-11-11', 'ימי א׳ 17:30', 6, 'frontal', 'רמת גן', 'רמת גן, ליד הבורסה', 80, 5, 'open', '2026-10-20T10:00:00Z'),
  ('610c8753-026b-518c-aec9-32a7269f1c09', '0cc19d22-7e4d-5e1f-a828-5e7aca3ae7d7', 'מרתון אנגלית לבגרות 5 יח״ל', 'אנגלית', '5 יח״ל', 'Unseen, writing ו־literature בארבע שעות מרוכזות, עם בחינה לדוגמה ובדיקה אישית של החיבור.', '2026-11-22', '10:00–14:00', 1, 'frontal', 'כפר סבא', 'כפר סבא, מתנ״ס בן גוריון', 120, 10, 'open', '2026-10-20T10:00:00Z'),
  ('a08f51a1-69ad-56b4-ac0d-c21380353b04', '050961cb-a3b4-5776-a3f6-3e0919f22837', 'חדו״א 1 לקראת מועד א׳', 'מתמטיקה', 'אקדמיה', 'גבולות, נגזרות, אינטגרלים וטורים. פותרים מבחנים קודמים של האוניברסיטאות.', '2026-11-27', 'ימי ה׳ 19:00', 4, 'online', null, null, 100, 15, 'open', '2026-10-20T10:00:00Z');
